    .rozpis-omsi.rozpis-omsi--vertical .skeleton-card {
      box-sizing: border-box;
      min-height: 64px;
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      align-items: center;
      gap: 10px 12px;
      padding: 12px 14px;
      background: rgba(234, 243, 247, 0.9);
      border: 1px solid rgba(160, 182, 194, 0.4);
      border-radius: 14px;
