if (!function_exists('my_tabs_slugify')) {
    // Prevedie text na URL hash slug (bez diakritiky, lowercase, medzery na pomlčky)
    function my_tabs_slugify($text)
    {
        $diacritics_map = [
            'á' => 'a',
            'ä' => 'a',
            'č' => 'c',
            'ď' => 'd',
            'é' => 'e',
            'ě' => 'e',
            'í' => 'i',
            'ľ' => 'l',
            'ĺ' => 'l',
            'ň' => 'n',
            'ó' => 'o',
            'ô' => 'o',
            'ŕ' => 'r',
            'š' => 's',
            'ť' => 't',
            'ú' => 'u',
            'ů' => 'u',
            'ý' => 'y',
            'ž' => 'z',
            'Á' => 'A',
            'Ä' => 'A',
            'Č' => 'C',
            'Ď' => 'D',
            'É' => 'E',
            'Ě' => 'E',
            'Í' => 'I',
            'Ľ' => 'L',
            'Ĺ' => 'L',
            'Ň' => 'N',
            'Ó' => 'O',
            'Ô' => 'O',
            'Ŕ' => 'R',
            'Š' => 'S',
            'Ť' => 'T',
            'Ú' => 'U',
            'Ů' => 'U',
            'Ý' => 'Y',
            'Ž' => 'Z',
        ];

        $text = strtr($text, $diacritics_map);
        $text = strtolower($text);
        $text = preg_replace('/[^a-z0-9]+/', '-', $text);

        return trim($text, '-');
    }
}

if (!function_exists('my_tabs_label_max_width')) {
    // Pre viacslovné texty vráti užšiu šírku (v "ch"), aby sa pekne zalomili na 2+ riadky namiesto roztiahnutia na celú šírku tlačidla; jedno dlhé slovo si šírku nevyžiada (0 = bez obmedzenia)
    function my_tabs_label_max_width($label)
    {
        $words = array_filter(preg_split('/\s+/u', trim($label)));
        if (count($words) <= 1) {
            return 0;
        }

        $chars = function_exists('mb_strlen') ? mb_strlen($label, 'UTF-8') : strlen($label);

        return max(8, (int) ceil($chars * 0.62));
    }
}

if (!function_exists('my_tabs_sanitize_name')) {
    // Očistí "name" atribút pre použitie v HTML id/data atribútoch, zachová veľkosť písmen
    function my_tabs_sanitize_name($name)
    {
        $name = preg_replace('/[^A-Za-z0-9_-]/', '', $name);

        return trim($name, '-_');
    }
}

