        <script>
            document.addEventListener("DOMContentLoaded", function() {
                var instances = [];

                document.querySelectorAll(".custom-tabs[data-tabs]").forEach(function(nav) {
                    var mapping;
                    try {
                        mapping = JSON.parse(nav.getAttribute("data-tabs"));
                    } catch (e) {
                        return;
                    }
                    if (!mapping || !mapping.length) {
                        return;
                    }

                    var buttons = {};
                    nav.querySelectorAll("[data-tab]").forEach(function(button) {
                        buttons[button.getAttribute("data-tab")] = button;
                    });

                    var contents = {};
                    mapping.forEach(function(item) {
                        contents[item.slug] = document.getElementById(item.contentId);
                    });

                    var slugs = mapping.map(function(item) {
                        return item.slug;
                    });

                    var instance = {
                        slugs: slugs,
                        current: null
                    };

                    function showTab(slug, updateUrl) {
                        if (slugs.indexOf(slug) === -1) {
                            slug = slugs[0];
                        }

                        Object.keys(contents).forEach(function(key) {
                            var content = contents[key];
                            if (content) {
                                content.classList.remove("custom-tabs__content--visible");
                                content.style.display = "none";
                            }
                        });

                        Object.keys(buttons).forEach(function(key) {
                            buttons[key].classList.remove("active");
                            buttons[key].setAttribute("aria-selected", "false");
                        });

                        var activeContent = contents[slug];
                        if (activeContent) {
                            activeContent.classList.add("custom-tabs__content");
                            activeContent.style.display = "block";

                            requestAnimationFrame(function() {
                                activeContent.classList.add("custom-tabs__content--visible");
                            });
                        }

                        var activeButton = buttons[slug];
                        if (activeButton) {
                            activeButton.classList.add("active");
                            activeButton.setAttribute("aria-selected", "true");
                        }

                        instance.current = slug;

                        if (updateUrl) {
                            history.pushState(null, "", "#" + slug);
                        }
                    }

                    instance.showTab = showTab;

                    Object.keys(buttons).forEach(function(slug) {
                        buttons[slug].addEventListener("click", function(event) {
                            event.preventDefault();
                            showTab(slug, true);
                        });
                    });

                    var initialHash = window.location.hash.replace("#", "");
                    showTab(slugs.indexOf(initialHash) !== -1 ? initialHash : slugs[0], false);

                    instances.push(instance);
                });

                function syncFromHash() {
                    var hash = window.location.hash.replace("#", "");
                    instances.forEach(function(instance) {
                        if (instance.slugs.indexOf(hash) !== -1 && instance.current !== hash) {
                            instance.showTab(hash, false);
                        }
                    });
                }

                // Fungovanie tlačidiel Späť / Dopredu a priamych odkazov s hashom
                window.addEventListener("popstate", syncFromHash);
                window.addEventListener("hashchange", syncFromHash);
            });
        </script>
    <?php
        return ob_get_clean();
    }
}

if (!function_exists('my_tabs_shortcode')) {
    function my_tabs_shortcode($atts)
    {
        static $assets_printed = false;

        $atts = shortcode_atts(
            [
                'name' => '',
                'buttons' => '',
            ],
            $atts,
            'myTabs'
        );

        $name = my_tabs_sanitize_name($atts['name']);
        if ($name === '') {
            return '';
        }

        $labels = array_values(array_filter(array_map('trim', explode(';', $atts['buttons']))));
        if (empty($labels)) {
            return '';
        }

        $tabs = [];
        $used_slugs = [];
        foreach ($labels as $index => $label) {
            $base_slug = my_tabs_slugify($label);
            $slug = $base_slug;
            $suffix = 2;
            while (isset($used_slugs[$slug])) {
                $slug = $base_slug . '-' . $suffix;
                $suffix++;
            }
            $used_slugs[$slug] = true;

            $tabs[] = [
                'label' => $label,
                'labelMaxWidth' => my_tabs_label_max_width($label),
                'slug' => $slug,
                'contentId' => $name . ($index + 1),
            ];
        }

        $data_tabs = wp_json_encode(
            array_map(function ($tab) {
                return ['slug' => $tab['slug'], 'contentId' => $tab['contentId']];
            }, $tabs)
        );

        $aria_label = implode(' / ', wp_list_pluck($tabs, 'label'));

        ob_start();
    ?>
        <nav
            class="custom-tabs"
            data-name="<?php echo esc_attr($name); ?>"
            data-tabs='<?php echo esc_attr($data_tabs); ?>'
