                        id="tabs-<?php echo esc_attr($name); ?>-btn-<?php echo (int) ($index + 1); ?>"
                        class="custom-tabs__button"
                        type="button"
                        role="tab"
                        data-tab="<?php echo esc_attr($tab['slug']); ?>"
                        aria-controls="<?php echo esc_attr($tab['contentId']); ?>"
                        aria-selected="false"><span class="custom-tabs__button-label" <?php echo $tab['labelMaxWidth'] ? ' style="max-width: ' . (int) $tab['labelMaxWidth'] . 'ch;"' : ''; ?>><?php echo esc_html($tab['label']); ?></span></button>
                <?php endforeach; ?>
            </div>
        </nav>
<?php
        $output = ob_get_clean();

        if (!$assets_printed) {
            $assets_printed = true;
            $output .= my_tabs_render_assets();
        }

        return $output;
