/**
 * Mamateyka – Breakdance restrictions
 *
 * Applies to all users with the "subscriber" role (Builder Access = Full
 * Interface), e.g. user ID 7 = Fotograf Polak. Full Interface means
 * Breakdance's own isPostTypeAllowed()/hasPermission() checks no longer
 * restrict anything, so every restriction below is enforced independently.
 *
 * Blocked for the restricted role:
 * - Opening AND saving Header / Footer / Templates / Popups / Global Blocks
 * - Managing (list/duplicate/delete/restore/empty trash) those post types
 * - Saving Global Styles / Selectors, Global Settings, Presets, Variables
 *   (via their standalone AJAX routes and via the combined page-save route)
 * - The corresponding admin menu entries
 *
 * Breakdance Settings is intentionally not handled here: it already
 * requires the WP "manage_options" capability, which this role lacks.
 */


function mamateyka_is_breakdance_restricted_user()
{
    return is_user_logged_in() && in_array('subscriber', wp_get_current_user()->roles, true);
}

/**
 * Post types Breakdance itself only allows with "Full" permission; must be re-blocked here.
 */
function mamateyka_get_breakdance_restricted_post_types()
{
    return array(
        BREAKDANCE_HEADER_POST_TYPE,
        BREAKDANCE_FOOTER_POST_TYPE,
        BREAKDANCE_TEMPLATE_POST_TYPE,
        BREAKDANCE_POPUP_POST_TYPE,
        BREAKDANCE_BLOCK_POST_TYPE,
    );
}

function mamateyka_send_breakdance_403()
{
    status_header(403);

    wp_send_json_error(
        array(
            'message' => 'You do not have permission to perform this Breakdance action.',
        ),
        403
    );
}

/**
 * Block selected Breakdance AJAX actions unconditionally, BEFORE Breakdance executes them.
 */
function mamateyka_block_breakdance_global_ajax()
{
    if (!mamateyka_is_breakdance_restricted_user()) {
        return;
    }

    mamateyka_send_breakdance_403();
}

foreach (
    array(
        // Global Styles / Selectors, Settings, Presets, Variables (standalone save routes).
        'wp_ajax_breakdance_save_selectors',
        'wp_ajax_breakdance_save_global_settings',
        'wp_ajax_breakdance_save_presets',
        'wp_ajax_breakdance_save_variables',
        'wp_ajax_breakdance_save_oxy_selectors',
        // Templates/Headers/Footers/Popups/Global Blocks management screen.
        'wp_ajax_breakdance_manage_templates_load_data',
        'wp_ajax_breakdance_manage_templates_save',
        'wp_ajax_breakdance_manage_templates_duplicate',
        'wp_ajax_breakdance_manage_templates_delete',
        'wp_ajax_breakdance_manage_templates_restore',
        'wp_ajax_breakdance_manage_templates_empty_trash',
        'wp_ajax_breakdance_manage_global_blocks',
    ) as $mamateyka_restricted_action
) {
    add_action($mamateyka_restricted_action, 'mamateyka_block_breakdance_global_ajax', 1);
}


/**
 * Prevent even opening the builder for a restricted post type (Header/Footer/Templates/Popups/Global Blocks).
 */
function mamateyka_block_breakdance_load_document()
{
    if (!mamateyka_is_breakdance_restricted_user()) {
        return;
    }

    $post_id = filter_input(INPUT_POST, 'id', FILTER_VALIDATE_INT);
    $post_type = $post_id ? get_post_type($post_id) : false;

    if ($post_type && in_array($post_type, mamateyka_get_breakdance_restricted_post_types(), true)) {
        mamateyka_send_breakdance_403();
    }
}
add_action('wp_ajax_breakdance_load_document', 'mamateyka_block_breakdance_load_document', 1);


/**
 * The builder always submits the full Global Styles state, changed or not; only block if it actually differs from what's stored.
 */
function mamateyka_did_breakdance_global_data_change()
{
    $simple_fields = array(
        'globalSettings' => 'global_settings_json_string',
        'classes'        => 'breakdance_classes_json_string',
        'presets'        => 'presets_json_string',
    );

    foreach ($simple_fields as $post_key => $option_key) {
        $submitted = filter_input(INPUT_POST, $post_key, FILTER_UNSAFE_RAW);

        if ($submitted === null || $submitted === '') {
            continue;
        }

        if ($submitted !== \Breakdance\Data\get_global_option($option_key)) {
            return true;
        }
    }

    // Stored the same way Breakdance itself decodes/compares them (see saveVariables()/saveSelectors()).
    $decoded_fields = array(
        'variables'    => array('variables_json_string', 'variables'),
        'oxySelectors' => array('oxy_selectors_json_string', 'selectors'),
    );

    foreach ($decoded_fields as $post_key => $mapping) {
        list($option_key, $data_key) = $mapping;
        $submitted = filter_input(INPUT_POST, $post_key, FILTER_UNSAFE_RAW);

        if ($submitted === null || $submitted === '') {
            continue;
        }

        $decoded = json_decode(str_replace('{}', 'null', $submitted), true);
        $submitted_value = $decoded[$data_key] ?? null;

        if ($submitted_value !== \Breakdance\Data\get_global_option($option_key)) {
            return true;
        }
    }

    return false;
}

/**
 * The combined page-save request also carries Global Styles/Header/Footer/Template data, so it needs its own guard.
 */
function mamateyka_block_breakdance_combined_save()
{
    if (!mamateyka_is_breakdance_restricted_user()) {
        return;
    }

    $post_id = filter_input(INPUT_POST, 'id', FILTER_VALIDATE_INT);
    $post_type = $post_id ? get_post_type($post_id) : false;
    $is_restricted_post_type = $post_type && in_array($post_type, mamateyka_get_breakdance_restricted_post_types(), true);

    if ($is_restricted_post_type || mamateyka_did_breakdance_global_data_change()) {
        mamateyka_send_breakdance_403();
    }
}
add_action('wp_ajax_breakdance_save', 'mamateyka_block_breakdance_combined_save', 1);


