/**
 * Subscribers lack "upload_files" by default, which also hides the Breakdance media picker; grant only that capability.
 */
function mamateyka_allow_restricted_user_media_library($allcaps, $caps, $args, $user)
{
    if (!$user || !in_array('subscriber', (array) $user->roles, true)) {
        return $allcaps;
    }

    if (isset($args[0]) && $args[0] === 'upload_files') {
        $allcaps['upload_files'] = true;
    }

    return $allcaps;
}
add_filter('user_has_cap', 'mamateyka_allow_restricted_user_media_library', 10, 4);


/**
 * The granted upload_files is meant for images only, since the use case is choosing/uploading photos.
 */
function mamateyka_restrict_restricted_user_upload_mimes($mimes)
{
    if (!mamateyka_is_breakdance_restricted_user()) {
        return $mimes;
    }

    return array_filter($mimes, function ($mime) {
        return strpos($mime, 'image/') === 0;
    });
}
